      { q: '触媒の性質として正しいものは？', c: ['反応の前後で自分は変化しない', '反応の材料として使いきられる', '反応を必ずおそくする', '生物の体の中にしか存在しない'], e: '触媒は反応を速めますが、自分は変化しないのでくり返しはたらけます。' },
      { q: 'カタラーゼが過酸化水素を分解したときにできるものは？', c: ['水と酸素', '水と水素', '二酸化炭素と水', '酸素と水素'], e: '2H₂O₂ → 2H₂O ＋ O₂ で、水と酸素ができます。' },
      { q: '酵素が決まった基質にしかはたらかない性質を何という？', c: ['基質特異性', '最適温度', '恒常性', '失活'], e: '活性部位に形の合う基質だけが結合するため、基質特異性があります。' },
      { q: '酵素の中で基質が結合する部分を何という？', c: ['活性部位', '細胞小器官', '高エネルギー部位', '補償点'], e: '酵素の基質と結合する部分を活性部位といいます。' },
      { q: '胃ではたらくペプシンの最適pHに最も近いものは？', c: ['約 2', '約 5', '約 7', '約 8'], e: '胃の中は強い酸性で、ペプシンの最適pHは約2です。' },
      { q: '酵素液を煮沸してから過酸化水素水に加えるとどうなる？', c: ['ほとんど泡が出ない', '泡がはげしく出る', '泡の色が変わる', '酸化マンガンになる'], e: '酵素は高温で変性して失活するので、反応がほとんど起こりません。' },
      { q: '酸化マンガン(IV)を加熱してから過酸化水素水に加えるとどうなる？', c: ['泡が出る', 'ほとんど泡が出ない', '水素が発生する', '溶けてなくなる'], e: '無機触媒は高温でも変性しないので、加熱後もはたらいて酸素が出ます。' },
      { q: '呼吸にかかわる酵素が多くはたらく細胞小器官は？', c: ['ミトコンドリア', '葉緑体', '液胞', '細胞壁'], e: '呼吸の多くの反応はミトコンドリアで、それぞれの酵素によって進みます。' },
      { q: '細胞の外に出されてはたらく酵素の例は？', c: ['アミラーゼ', 'DNA を複製する酵素', '光合成の酵素', '呼吸の酵素'], e: 'アミラーゼなどの消化酵素は、細胞外（消化管内）に分泌されてはたらきます。' }
